dataUI <- function(){cloud<-identical(worthwhile_mode(),'supabase');tagList(tags$h2(if(cloud)'Your private plan and backups.'else'Your plan, kept locally.'),tags$p(if(cloud)'Your plan is saved to your signed-in Supabase account. Other users have separate records. Download a JSON backup whenever you need an independent copy.'else'Local mode keeps one personal plan on this computer. Use Supabase mode for a shared deployment.'),
 fluidRow(column(5,section('Preferences',textInput('currency','Currency label','EUR'),selectInput('timezone','Timezone',OlsonNames(),'Europe/Prague'),numericInput('fulltime','Full-time hours per week',40,min=1,max=100),actionButton('settings','Save preferences',class='btn-primary'))),column(7,section('Backups & data',downloadButton('backup','Download complete JSON backup'),fileInput('restore','Restore a JSON backup',accept='.json'),tags$p(class='hint','Schemas 1, 2 and 3 migrate without guessing missing actual times. The previous good save is retained. Local files also keep a pre-migration snapshot. Restoring replaces the current plan only after confirmation. Undo works in this session.'),actionButton('empty','Start a blank plan',class='btn-quiet'),actionButton('demo','Load scientist example',class='btn-quiet'),tags$p(class='hint','Keep an independent JSON backup before moving your plan to another computer. See the setup guide for cloud configuration or a personal local save.')))),
 accordion('How decisions and money are calculated',tags$p('Priority tiers protect consequence 5/5 and fixed deadlines within two days, then other fixed deadlines within a week. Your selected lens orders tasks within each tier; unresolved dependencies stay blocked.'),tags$p('Salary is shown once as fixed income. It is not earned again per task. Hourly work and paid units generate marginal estimates; guaranteed bonuses and entered expenses are included. Net means before tax. Accrued work estimates are not cash receipts.'),tags$p('The scheduler is a transparent greedy heuristic. Locked blocks, protected life, dated exceptions and fixed deadlines constrain it. Future-wealth scenarios use your assumptions, not calibrated predictions. A task can matter without generating money.'),tags$p('Start / Pause / Resume preserve focus and context; no live elapsed-time timer runs. Save actual work sessions manually. Remaining effort is a separate forecast and is never reduced merely because hours were logged.')))

}
